//! Generated outputs: write them all, or compare them with what is on disk.

use std::fs;
use std::path::{Component, Path, PathBuf};

/// One generated file.
pub struct Output {
    /// Relative to the repository root.
    pub path: PathBuf,
    pub bytes: Vec<u8>,
    /// Binary outputs are byte-compared only on the CI platform (Linux `x86_64`).
    pub binary: bool,
}

/// Whether binary outputs can be compared byte for byte on this host.
pub const BYTE_EXACT: bool = cfg!(all(target_os = "linux", target_arch = "x86_64"));

fn is_safe(path: &Path) -> bool {
    !path.as_os_str().is_empty() && path.components().all(|c| matches!(c, Component::Normal(_)))
}

/// Writes every output under `root`, creating folders as needed.
pub fn write_all(root: &Path, outs: &[Output]) -> Result<(), Vec<String>> {
    let mut errors = Vec::new();
    for out in outs {
        if !is_safe(&out.path) {
            errors.push(format!("{}: unsafe output path", out.path.display()));
            continue;
        }
        let full = root.join(&out.path);
        if fs::symlink_metadata(&full).is_ok_and(|m| m.file_type().is_symlink()) {
            errors.push(format!(
                "{}: is a symlink, refusing to write through it",
                full.display()
            ));
            continue;
        }
        if let Some(Err(e)) = full.parent().map(|parent| {
            fs::create_dir_all(parent).map_err(|e| format!("{}: {e}", parent.display()))
        }) {
            errors.push(e);
            continue;
        }
        if let Err(e) = fs::write(&full, &out.bytes) {
            errors.push(format!("{}: {e}", full.display()));
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors)
    }
}

/// The outputs whose file is missing or differs from the generated bytes.
pub fn check_all(root: &Path, outs: &[Output]) -> Vec<PathBuf> {
    check_with(root, outs, BYTE_EXACT)
}

/// [`check_all`] with the byte-exact decision passed in.
fn check_with(root: &Path, outs: &[Output], byte_exact: bool) -> Vec<PathBuf> {
    outs.iter()
        .filter(|out| {
            let full = root.join(&out.path);
            if out.binary && !byte_exact {
                return !full.is_file();
            }
            fs::read(&full).map_or(true, |on_disk| on_disk != out.bytes)
        })
        .map(|out| out.path.clone())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn out(path: &str, bytes: &[u8]) -> Output {
        Output {
            path: PathBuf::from(path),
            bytes: bytes.to_vec(),
            binary: false,
        }
    }

    #[test]
    fn check_reports_changed_and_missing_only() {
        let dir = tempfile::tempdir().unwrap();
        write_all(
            dir.path(),
            &[out("a/same.txt", b"x"), out("a/changed.txt", b"old")],
        )
        .unwrap();
        let want = [
            out("a/same.txt", b"x"),
            out("a/changed.txt", b"new"),
            out("a/missing.txt", b"m"),
        ];
        let stale = check_all(dir.path(), &want);
        assert_eq!(
            stale,
            vec![
                PathBuf::from("a/changed.txt"),
                PathBuf::from("a/missing.txt")
            ]
        );
    }

    #[test]
    fn binary_outputs_are_byte_compared_only_when_exact() {
        let dir = tempfile::tempdir().unwrap();
        let bin = |bytes: &[u8]| Output {
            binary: true,
            ..out("m.png", bytes)
        };
        write_all(dir.path(), &[bin(b"old")]).unwrap();
        let want = [bin(b"new")];
        assert_eq!(
            check_with(dir.path(), &want, true),
            vec![PathBuf::from("m.png")]
        );
        assert_eq!(check_with(dir.path(), &want, false).len(), 0);
        let missing = [Output {
            binary: true,
            ..out("gone.png", b"x")
        }];
        assert_eq!(check_with(dir.path(), &missing, false).len(), 1);
        assert_eq!(check_with(dir.path(), &missing, true).len(), 1);
    }

    #[test]
    fn rejects_paths_that_escape_root() {
        let dir = tempfile::tempdir().unwrap();
        assert!(write_all(dir.path(), &[out("../evil.txt", b"x")]).is_err());
        assert!(write_all(dir.path(), &[out("/abs.txt", b"x")]).is_err());
    }

    #[cfg(unix)]
    #[test]
    fn refuses_to_write_through_a_symlink() {
        let dir = tempfile::tempdir().unwrap();
        let elsewhere = dir.path().join("elsewhere.txt");
        fs::write(&elsewhere, b"keep").unwrap();
        std::os::unix::fs::symlink(&elsewhere, dir.path().join("link.txt")).unwrap();
        let e = write_all(dir.path(), &[out("link.txt", b"overwritten")]).unwrap_err();
        assert!(e[0].contains("symlink"), "{e:?}");
        assert_eq!(fs::read(&elsewhere).unwrap(), b"keep");
    }
}
